// M4 acceptance (the "on attest envelopes" link): a report generated by whiffin
// verifies END TO END under attest's M1 `verifyDuedaleReport` when the venture-
// branded envelope type + genesis label are passed — proving duedale-angel's
// /report flow can consume @kashscript/whiffin and stay verifiable offline.

import { describe, expect, it } from "bun:test";
import { verifyDuedaleReport } from "@kashscript/attest/compat";

import { buildVendorAllowlist, generateGrantAuthorityKeyPair } from "../src/mandate/grant";
import { InMemoryGrantLedger, InMemoryNonceStore, issueGrant, markDelivered, redeemGrant } from "../src/mandate/lifecycle";
import { assembleSignedReport, signReport, verifyReportSignature } from "../src/report";
import { EXAMPLE_VENDORS, exampleProgram } from "./fixtures";

const NOW = 1_800_000_000;
const program = exampleProgram();
const VENDOR = EXAMPLE_VENDORS[0];

describe("report ⇄ attest — whiffin generates, attest verifies (offline)", () => {
  it("verifies under attest.verifyDuedaleReport with the duedale-branded envelope", async () => {
    const kp = await generateGrantAuthorityKeyPair();
    const ledger = new InMemoryGrantLedger();
    const nonces = new InMemoryNonceStore();

    const redeemed = await issueGrant(
      { programId: program.programId, beneficiaryDid: "did:kash:ben-1", purposeTag: "MEAL", amountPaisa: 250_000 },
      program,
      kp.privateKey,
      ledger,
      { nowUnix: NOW },
    );
    await issueGrant(
      { programId: program.programId, beneficiaryDid: "did:kash:ben-2", purposeTag: "GROCERY", amountPaisa: 100_000 },
      program,
      kp.privateKey,
      ledger,
      { nowUnix: NOW },
    );
    const allowlist = await buildVendorAllowlist(program.approvedVendorDids);
    await markDelivered(redeemed.signed.grant.grantId, ledger, { nowUnix: NOW + 60 });
    await redeemGrant(
      { grantId: redeemed.signed.grant.grantId, vendorDid: VENDOR, beneficiaryDid: "did:kash:ben-1", purposeTag: "MEAL", vendorProof: allowlist.proofByDid.get(VENDOR)! },
      kp.publicKey,
      ledger,
      nonces,
      { nowUnix: NOW + 120 },
    );

    const signed = await assembleSignedReport(await ledger.list(), program, kp, {
      nowUnix: NOW + 86_400,
      eventType: "duedale/every-rupee-report",
      genesisLabel: "duedale-every-rupee-chain-v1",
    });

    // Verify with an explicit operator key.
    const result = await verifyDuedaleReport(signed, kp.publicKey);
    expect(result.ok).toBe(true);
    expect(result.signatureOk).toBe(true);
    expect(result.chain.ok).toBe(true);

    // And from the embedded operator-key hex alone (fresh-machine posture).
    const fromEmbedded = await verifyDuedaleReport(signed);
    expect(fromEmbedded.ok).toBe(true);
  });
  it("a report that still carries 0.1.0's retired states and totals keeps verifying (compat path)", async () => {
    // 0.2.0 narrowed the lifecycle to ISSUED · DELIVERED · REDEEMED · EXPIRED and dropped the
    // two totals for value paid out and returned. Reports signed under the wider 0.1.0 shape are
    // checked over their own JSON, so they must still verify — here and under attest, offline.
    const kp = await generateGrantAuthorityKeyPair();
    const ledger = new InMemoryGrantLedger();
    const issued = await issueGrant(
      { programId: program.programId, beneficiaryDid: "did:kash:ben-1", purposeTag: "MEAL", amountPaisa: 250_000 },
      program,
      kp.privateKey,
      ledger,
      { nowUnix: NOW },
    );
    const id = issued.signed.grant.grantId;
    for (const [i, toState] of ["REDEEMED", "SETTLED"].entries()) {
      await ledger.recordTransition(id, {
        grantId: id,
        toState: toState as never, // "SETTLED" is not in the 0.2.0 union — it is a 0.1.0 row
        actorDid: "did:kash:vendor-canteen",
        actorClass: "PROTOCOL",
        reason: "recorded under 0.1.0",
        code: null,
        atUnix: NOW + 60 + i,
      });
    }
    const options = { nowUnix: NOW + 86_400, eventType: "duedale/every-rupee-report", genesisLabel: "duedale-every-rupee-chain-v1" };
    const modern = await assembleSignedReport(await ledger.list(), program, kp, options);
    // Re-create the 0.1.0 report body: the two retired totals back in, the row in a retired state.
    const legacyReport = {
      ...modern.report,
      totals: { ...modern.report.totals, settledPaisa: 250_000, refundedPaisa: 0 },
    };
    expect(modern.report.grants[0]!.state as string).toBe("SETTLED");
    const legacy = await signReport(legacyReport, kp.privateKey, kp.publicKey, { eventType: options.eventType });

    expect(await verifyReportSignature(legacy, kp.publicKey, { eventType: options.eventType })).toBe(true);
    const result = await verifyDuedaleReport(legacy, kp.publicKey);
    expect(result.ok).toBe(true);
    expect(result.signatureOk).toBe(true);
    expect(result.chain.ok).toBe(true);
  });
});
